// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // Fund the contract with a fixed, admissible balance.
        vm.deal(address(c), 1 ether);
        // Keep the fuzz domain wide: any amount strictly greater than the balance.
        vm.assume(amount > 1 ether);
        vm.assume(receiver != address(0) && receiver != address(c));

        // The deployer (this test contract) is the owner of c.
        bool ok;
        vm.prank(address(this));
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

        // General rule: sending more than the contract's balance must revert.
        assertTrue(!ok, "sendTo with amount > balance must revert");
    }
}
